const net = require('net');
const { EventEmitter } = require('events');

class ConnectionPool extends EventEmitter {
  constructor(maxSize = 10) {
    super();
    this.pool = new Map();
    this.maxSize = maxSize;
    this.sequence = 0;
  }

  acquire(target) {
    const key = `${target.host}:${target.port}`;
    let entry = this.pool.get(key);
    if (entry && entry.socket && !entry.socket.destroyed) {
      entry.refCount++;
      entry.lastUsed = Date.now();
      return entry;
    }
    const socket = net.createConnection(target.port, target.host);
    entry = {
      id: ++this.sequence,
      socket,
      refCount: 1,
      lastUsed: Date.now(),
      key,
      metadata: Buffer.alloc(256)
    };
    this.pool.set(key, entry);
    return entry;
  }

  release(entry) {
    entry.refCount--;
    if (entry.refCount <= 0) {
      this.scheduleCleanup(entry);
    }
  }

  scheduleCleanup(entry) {
    setImmediate(() => {
      if (entry.refCount <= 0) {
        entry.socket.destroy();
        entry.metadata.fill(0);
        entry.metadata = null;
        this.pool.delete(entry.key);
        this.emit('cleaned', entry.id);
      }
    });
  }
}

class ProxySession {
  constructor(clientSocket, pool) {
    this.client = clientSocket;
    this.pool = pool;
    this.entry = null;
    this.state = 'init';
    this.buffer = [];
  }

  async handleRequest(data) {
    const target = this.parseTarget(data);
    if (!target) {
      this.client.end('HTTP/1.1 400 Bad Request\r\n\r\n');
      return;
    }

    this.entry = this.pool.acquire(target);
    this.state = 'connected';

    await this.forwardData(data);
    await this.pipeResponse();
  }

  async forwardData(data) {
    return new Promise((resolve, reject) => {
      if (!this.entry || !this.entry.socket) {
        reject(new Error('No connection'));
        return;
      }
      this.entry.socket.write(data, (err) => {
        if (err) reject(err);
        else resolve();
      });
    });
  }

  async pipeResponse() {
    const entry = this.entry;
    return new Promise((resolve, reject) => {
      entry.socket.on('data', (chunk) => {
        this.client.write(chunk);
      });
      entry.socket.on('end', () => {
        this.pool.release(entry);
        resolve();
      });
      entry.socket.on('error', (err) => {
        this.pool.release(entry);
        reject(err);
      });
    });
  }

  parseTarget(data) {
    const header = data.toString('utf8');
    const match = header.match(/Host:\s*([^:\r\n]+)(?::(\d+))?/i);
    if (!match) return null;
    return { host: match[1].trim(), port: parseInt(match[2] || '80', 10) };
  }

  destroy() {
    if (this.entry) {
      this.pool.release(this.entry);
      this.entry = null;
    }
    this.state = 'destroyed';
  }
}

class ProxyServer {
  constructor(port) {
    this.port = port;
    this.pool = new ConnectionPool(50);
    this.sessions = new Set();
    this.server = net.createServer((socket) => this.onConnection(socket));
  }

  onConnection(clientSocket) {
    const session = new ProxySession(clientSocket, this.pool);
    this.sessions.add(session);

    clientSocket.on('data', async (data) => {
      try {
        await session.handleRequest(data);
      } catch (err) {
        clientSocket.end();
      }
    });

    clientSocket.on('close', () => {
      session.destroy();
      this.sessions.delete(session);
    });

    clientSocket.on('error', () => {
      session.destroy();
      this.sessions.delete(session);
    });
  }

  listen() {
    this.server.listen(this.port, () => {
      console.log(`Proxy listening on port ${this.port}`);
    });
  }
}

const proxy = new ProxyServer(8080);
proxy.listen();
